import{_ as a,o as e,c as n}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse(`{"title":"performance Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"performance","tag":"performance","title":"performance Tag","prev":null,"next":null,"posts":[{"title":"JavaScript的加载优化","url":"/posts/2021-01-23-javascript-performance/","date":"2021-01-23 16:11","tags":["performance"],"html":"<p>前端开发中，JavaScript 变得越来越重要，页面载入中，JavaScript 占的比重也更高。不同与别的静态资源，例如图片和 SVG 图标。浏览器在解析 JavaScript 时花的时间要多得多。所以优化 JavaScript 也就变得非常重要。</p>\\n<h2 id=\\"减少-javascript-的网络传输开销\\" tabindex=\\"-1\\">减少 JavaScript 的网络传输开销 <a class=\\"header-anchor\\" href=\\"#减少-javascript-的网络传输开销\\" aria-label=\\"Permalink to &quot;减少 JavaScript 的网络传输开销&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"only-sending-the-code-a-user-needs\\" tabindex=\\"-1\\">Only sending the code a user needs. <a class=\\"header-anchor\\" href=\\"#only-sending-the-code-a-user-needs\\" aria-label=\\"Permalink to &quot;Only sending the code a user needs.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>一方面，只加载当前页面需要的 JavaScript 文件，可以使用 webpack 的<a href=\\"https://webpack.js.org/guides/code-splitting/\\" target=\\"_blank\\" rel=\\"noreferrer\\">code-splitting</a>来解决。另一方面，懒加载一些不是必须的 JavaScript 文件。</p>\\n<h3 id=\\"minification\\" tabindex=\\"-1\\">Minification <a class=\\"header-anchor\\" href=\\"#minification\\" aria-label=\\"Permalink to &quot;Minification&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>使用<a href=\\"https://github.com/terser/terser\\" target=\\"_blank\\" rel=\\"noreferrer\\">terser</a>来压缩 JavaScript 代码。</p>\\n<h3 id=\\"compression\\" tabindex=\\"-1\\">Compression <a class=\\"header-anchor\\" href=\\"#compression\\" aria-label=\\"Permalink to &quot;Compression&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>服务器开启 GZIP 来减少传输的文件大小。</p>\\n<h3 id=\\"removing-unused-code\\" tabindex=\\"-1\\">Removing unused code. <a class=\\"header-anchor\\" href=\\"#removing-unused-code\\" aria-label=\\"Permalink to &quot;Removing unused code.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>针对一些第三方 JavaScript 库，可以使用<a href=\\"https://webpack.js.org/guides/tree-shaking/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Tree Shaking</a>来移除不需要的代码。</p>\\n<h3 id=\\"caching-code-to-minimize-network-trips\\" tabindex=\\"-1\\">Caching code to minimize network trips. <a class=\\"header-anchor\\" href=\\"#caching-code-to-minimize-network-trips\\" aria-label=\\"Permalink to &quot;Caching code to minimize network trips.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>使用 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/ETag\\" target=\\"_blank\\" rel=\\"noreferrer\\">ETag</a>, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Last-Modified\\" target=\\"_blank\\" rel=\\"noreferrer\\">Last-Modified</a>, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control\\" target=\\"_blank\\" rel=\\"noreferrer\\">Cache-Control</a> 三个配合有效的缓存 JavaScript 文件。</p>\\n<h2 id=\\"优化-javascript-下载和执行\\" tabindex=\\"-1\\">优化 JavaScript 下载和执行 <a class=\\"header-anchor\\" href=\\"#优化-javascript-下载和执行\\" aria-label=\\"Permalink to &quot;优化 JavaScript 下载和执行&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们可以通过使用 <code>async</code> 或者 <code>defer</code> 来优化 JavaScript 的下载和执行，两个关键字的具体作用看下图：</p>\\n<p><img src=\\"/assets/js_async_defer.png\\" alt=\\"js async defer\\"></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 的优化并没有银弹，要根据具体项目的实际情况来处理。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTTP caching</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/javascript-startup-optimization?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">JavaScript Start-up Optimization</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/loading-third-party-javascript?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">Loading Third-Party JavaScript</a></p>\\n"},{"title":"前端开发中的加载性能优化","url":"/posts/2020-12-20-loading-performance/","date":"2020-12-20 10:48","tags":["web","performance"],"html":"<p>不同于需要安装的安卓 App 或者 iOS App，前端 App 所有的资源文件都要通过网络进行下载，所以加载速度越快对用户的体验来说就越好。因为我们也需要在加载的时候进行优化，减少不必要的资源请求。</p>\\n<h2 id=\\"文本内容的优化\\" tabindex=\\"-1\\">文本内容的优化 <a class=\\"header-anchor\\" href=\\"#文本内容的优化\\" aria-label=\\"Permalink to &quot;文本内容的优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"压缩代码\\" tabindex=\\"-1\\">压缩代码 <a class=\\"header-anchor\\" href=\\"#压缩代码\\" aria-label=\\"Permalink to &quot;压缩代码&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>HTML，JS，CSS 都有相应的工具可以进行代码压缩，可以使用 webpack 工具方便的进行代码压缩。JS 使用工具<a href=\\"https://github.com/terser/terser\\" target=\\"_blank\\" rel=\\"noreferrer\\">terser</a>，CSS 使用<a href=\\"https://github.com/cssnano/cssnano\\" target=\\"_blank\\" rel=\\"noreferrer\\">CSS Nano</a>, HTML 使用<a href=\\"https://github.com/kangax/html-minifier\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTMLMinifier</a>进行代码压缩。</p>\\n<h3 id=\\"使用-gzip-进行压缩\\" tabindex=\\"-1\\">使用 GZIP 进行压缩 <a class=\\"header-anchor\\" href=\\"#使用-gzip-进行压缩\\" aria-label=\\"Permalink to &quot;使用 GZIP 进行压缩&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>现代化浏览器都支持 GZIP 进行压缩，并且服务器端 NGINX 也可以很方便的配置使用 GZIP 压缩请求的资源文件。</p>\\n<h3 id=\\"减少第三方-js-的引用\\" tabindex=\\"-1\\">减少第三方 JS 的引用 <a class=\\"header-anchor\\" href=\\"#减少第三方-js-的引用\\" aria-label=\\"Permalink to &quot;减少第三方 JS 的引用&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>在 2010 年左右，人们都爱使用 jQuery 框架进行开发，因为 jQuery 抹平了浏览器之间的差异性，大大提高了开发效率。但随着浏览器吸收了 jQuery 的各种优点，例如可以使用<code>document.querySelector</code>很方便的像 jQuery 一样选择元素。现在的前端开发已经不那么需要 jQuery 了，你可以访问<a href=\\"http://youmightnotneedjquery.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">You might not need jQuery</a>来查找替代的方法。</p>\\n<h3 id=\\"webpack-相关的优化\\" tabindex=\\"-1\\">webpack 相关的优化 <a class=\\"header-anchor\\" href=\\"#webpack-相关的优化\\" aria-label=\\"Permalink to &quot;webpack 相关的优化&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>可以使用 webpack 的<a href=\\"https://webpack.js.org/plugins/split-chunks-plugin/\\" target=\\"_blank\\" rel=\\"noreferrer\\">SplitChunksPlugin</a>， 分割 JS 文件，只打包首次载入需要的 JS 文件来减少网络请求。\\n我们也可以使用<a href=\\"https://webpack.js.org/guides/tree-shaking/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Tree Shaking</a>来引入需要的 JS 库，避免不使用的代码被打包进来。</p>\\n<h2 id=\\"图像内容的优化\\" tabindex=\\"-1\\">图像内容的优化 <a class=\\"header-anchor\\" href=\\"#图像内容的优化\\" aria-label=\\"Permalink to &quot;图像内容的优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"移除不使用的图像\\" tabindex=\\"-1\\">移除不使用的图像 <a class=\\"header-anchor\\" href=\\"#移除不使用的图像\\" aria-label=\\"Permalink to &quot;移除不使用的图像&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>由于网站项目的更新，很多时候有一些不被使用的图像资源被打包进输出目录。这样会导致无谓的资源加载，需要及时发现和删除。</p>\\n<h3 id=\\"选择合适的图像格式\\" tabindex=\\"-1\\">选择合适的图像格式 <a class=\\"header-anchor\\" href=\\"#选择合适的图像格式\\" aria-label=\\"Permalink to &quot;选择合适的图像格式&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>众所周知，png 图像可以展示透明效果，但是 jpg 图像做不到。但是因为 png 比 jpg 多了一个 alpha 通道，所以占用的空间也大，如果不需要透明效果展示，相同的图像效果，jpg 会占用更小的空间。</p>\\n<h3 id=\\"移除图像的-metadata\\" tabindex=\\"-1\\">移除图像的 Metadata <a class=\\"header-anchor\\" href=\\"#移除图像的-metadata\\" aria-label=\\"Permalink to &quot;移除图像的 Metadata&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>图像的 Metadata 对于 web 资源来说并没有什么意义，所以移除 Metadata 可以减少图像占用空间。</p>\\n<h3 id=\\"调整图像尺寸\\" tabindex=\\"-1\\">调整图像尺寸 <a class=\\"header-anchor\\" href=\\"#调整图像尺寸\\" aria-label=\\"Permalink to &quot;调整图像尺寸&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>如果显示的尺寸和实际尺寸差距过大，也会造成不必要的资源浪费。</p>\\n<h3 id=\\"调整图像质量\\" tabindex=\\"-1\\">调整图像质量 <a class=\\"header-anchor\\" href=\\"#调整图像质量\\" aria-label=\\"Permalink to &quot;调整图像质量&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>在很多情况下，对图像质量没有过高的要求，可以损失质量来换取更小的空间。</p>\\n<h3 id=\\"压缩图像\\" tabindex=\\"-1\\">压缩图像 <a class=\\"header-anchor\\" href=\\"#压缩图像\\" aria-label=\\"Permalink to &quot;压缩图像&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>现在有很多算法可以有损或者无损的压缩图像，在发布之前，可以使用压缩工具减少图像的使用空间。</p>\\n<h2 id=\\"http-请求优化\\" tabindex=\\"-1\\">HTTP 请求优化 <a class=\\"header-anchor\\" href=\\"#http-请求优化\\" aria-label=\\"Permalink to &quot;HTTP 请求优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以使用 HTTP2 协议来提高网站的载入速度，HTTP2 允许多路复用，多个请求可以使用单一的 HTTP 连接来处理，大大提高了载入速度。\\n这里有一个<a href=\\"https://http2.akamai.com/demo\\" target=\\"_blank\\" rel=\\"noreferrer\\">demo</a> 大家可以使用浏览器打开，感受一下。</p>\\n<h2 id=\\"http-cache\\" tabindex=\\"-1\\">HTTP Cache <a class=\\"header-anchor\\" href=\\"#http-cache\\" aria-label=\\"Permalink to &quot;HTTP Cache&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以通过缓存技术来提高网站的载入速度，当用户再次访问网站的时候可以直接使用缓存而不必再次请求资源文件。我们甚至可以使用<a href=\\"https://developers.google.com/web/fundamentals/primers/service-workers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Service Workers</a>缓存整个网站，保证可以离线使用。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>载入优化需要从各个方面入手，查找分析前端 App 的资源文件，并从网络请求和缓存下手才能达到最优的效果。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/get-started\\" target=\\"_blank\\" rel=\\"noreferrer\\">Loading Performance</a></p>\\n"},{"title":"JavaScript开发中的性能优化","url":"/posts/2018-04-25-javascript-performance/","date":"2018-04-25 23:22","tags":["js","performance"],"html":"<p>最近工作比较清闲，5 月又换了一个工作环境。总结下最近看的有关 JavaScript 性能的知识，并记下来供未来的自己参考。希望自己能不忘初心，继续成长！</p>\\n<h2 id=\\"使用-requestanimationframe-来更新动画\\" tabindex=\\"-1\\">使用 requestAnimationFrame 来更新动画 <a class=\\"header-anchor\\" href=\\"#使用-requestanimationframe-来更新动画\\" aria-label=\\"Permalink to &quot;使用 requestAnimationFrame 来更新动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用<code>requestAnimationFrame</code>把动画渲染交给浏览器，可以保证渲染保持在 60FPS。应该避免使用<code>setTimeout</code>或者<code>setInterval</code>来实现动画，因为计时器和事件队列会消耗更多的资源，还会导致无用的页面重新绘制。</p>\\n<h2 id=\\"使用-web-workers-来进行复杂的运算\\" tabindex=\\"-1\\">使用 Web Workers 来进行复杂的运算 <a class=\\"header-anchor\\" href=\\"#使用-web-workers-来进行复杂的运算\\" aria-label=\\"Permalink to &quot;使用 Web Workers 来进行复杂的运算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以把单纯的计算放在 Web Workers 中，这样不影响主页面的渲染和流畅，例如加密和矩阵变换的运算就可以完全放在 Web Workers 中来减少主线程的执行时间，避免浏览器渲染堵塞。</p>\\n<h2 id=\\"避免微优化-javascript\\" tabindex=\\"-1\\">避免微优化 JavaScript <a class=\\"header-anchor\\" href=\\"#避免微优化-javascript\\" aria-label=\\"Permalink to &quot;避免微优化 JavaScript&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>举个最简单的例子，我曾经在一本书上看到过一个提升程序效率的例子。大致是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>这里的<code>array.length</code>获取数组的长度，每次都要计算数组长度会消耗不少时间，优化之后的代码是这样的：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> array </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#D73A49\\">...</span><span style=\\"color:#005CC5\\">100</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> len </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> array.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> len; i</span><span style=\\"color:#D73A49\\">++</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(array[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>通过缓存数组的长度来保证只计算一次。这就是典型的微优化，说实话这段代码我一直在用，直到最近读了其他的书才发现，现在的 JS 解释器早就优化了对数组长度的计算。无论是读取一次还是一万次消耗的时间都没有太大差别。微优化应该是 JS 引擎需要做的事情，我们不应该在实际开发中在这方面耗费过多的时间。</p>\\n<h2 id=\\"滑动事件优化\\" tabindex=\\"-1\\">滑动事件优化 <a class=\\"header-anchor\\" href=\\"#滑动事件优化\\" aria-label=\\"Permalink to &quot;滑动事件优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户监听滑动事件并执行相关动画操作的时候，记得使用<code>window.requestAnimationFrame</code>来优化动画的执行。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> onScroll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">evt</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // Prevent multiple rAF callbacks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scheduledAnimationFrame) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scheduledAnimationFrame </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> readAndUpdatePage</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // do something</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  requestAnimationFrame</span><span style=\\"color:#24292E\\">(readAndUpdatePage);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">addEventListener</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'scroll'</span><span style=\\"color:#24292E\\">, onScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br></div></div><p>参考：</p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/debounce-your-input-handlers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Debounce Your Input Handlers</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/optimize-javascript-execution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Optimize JavaScript Execution</a></p>\\n"}]},"relativePath":"tags/performance/index.md","filePath":"tags/[slug].md"}`),s={name:"tags/performance/index.md"};function r(o,t,p,l,i,c){return e(),n("div")}const u=a(s,[["render",r]]);export{h as __pageData,u as default};
